values.content:
Feature: {{ $json.data.feature_name }}
Description: {{ $json.data.feature_description }}
Priority: {{ $json.data.priority }}

Generate 5-8 specific tasks for this feature including frontend, backend, testing, and documentation.

parameters.jsCode:
// Parse AI response and structure tasks
try {
  const aiResponse = JSON.parse($input.item.json.message.content);
  const featureData = $input.item.json;

  // Get feature_id from the original webhook data
  const featureId = featureData.data ? featureData.data.feature_id : featureData.feature_id;

  // Ensure we have tasks array
  const tasks = aiResponse.tasks || [];

  // Validate and clean up tasks
  const validatedTasks = tasks.map(task => ({
    name: task.name || 'Unnamed Task',
    description: task.description || '',
    priority: Math.min(10, Math.max(1, parseInt(task.priority) || 5)),
    estimated_hours: parseInt(task.estimated_hours) || 4,
    skills: Array.isArray(task.skills) ? task.skills : [],
    dependencies: Array.isArray(task.dependencies) ? task.dependencies : []
  }));

  return [{
    feature_id: featureId,
    tasks: validatedTasks,
    original_feature: featureData.data || featureData,
    total_hours: validatedTasks.reduce((sum, task) => sum + task.estimated_hours, 0)
  }];
} catch (error) {
  // Fallback if AI fails
  const featureData = $input.item.json;
  const featureId = featureData.data ? featureData.data.feature_id : featureData.feature_id;

  return [{
    feature_id: featureId,
    tasks: [
      {
        name: 'Analyze Requirements',
        description: 'Review and document detailed requirements',
        priority: 8,
        estimated_hours: 2,
        skills: ['Analysis']
      },
      {
        name: 'Design Architecture',
        description: 'Create technical design and architecture',
        priority: 7,
        estimated_hours: 4,
        skills: ['Architecture']
      },
      {
        name: 'Implement Feature',
        description: 'Build the core functionality',
        priority: 9,
        estimated_hours: 8,
        skills: ['Development']
      },
      {
        name: 'Write Tests',
        description: 'Create comprehensive tests',
        priority: 6,
        estimated_hours: 3,
        skills: ['Testing']
      },
      {
        name: 'Create Documentation',
        description: 'Write user and technical docs',
        priority: 5,
        estimated_hours: 2,
        skills: ['Documentation']
      }
    ],
    original_feature: featureData.data || featureData,
    total_hours: 19
  }];
}
